INSERT INTO club_season (club_id, season, league_id) SELECT COALESCE((SELECT ca.club_id FROM club_aliases ca WHERE lower(ca.alias) = lower('Leeds United')), (SELECT club_id FROM club WHERE lower(name) = lower('Leeds United'))), 1, (SELECT league_id FROM league WHERE name = 'Premier League') WHERE COALESCE((SELECT ca.club_id FROM club_aliases ca WHERE lower(ca.alias) = lower('Leeds United')), (SELECT club_id FROM club WHERE lower(name) = lower('Leeds United'))) IS NOT NULL ON CONFLICT (club_id, season) DO NOTHING;
